package com.stocksentinel.custom;
import com.fasterxml.jackson.databind.ObjectMapper;import com.stocksentinel.strategy.StrategyMapper;import com.stocksentinel.indicator.IndicatorMapper;import com.stocksentinel.stock.WatchlistMapper;import com.stocksentinel.jobs.TradingDatePolicy;import com.stocksentinel.notification.*;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import java.util.*;
@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="custom-strategies.enabled",havingValue="true")
public class CustomStrategyConfiguration {
    @Bean CustomFactorReader customFactorReader(StrategyMapper bars,IndicatorMapper indicators,CustomStrategyMapper mapper,ObjectMapper json,TradingDatePolicy dates){return new CustomFactorReader(bars,indicators,mapper,json,dates);}
    @Bean CustomStrategyService customStrategyService(CustomStrategyMapper mapper,CustomFactorReader factors,WatchlistMapper stocks,TradingDatePolicy dates,ObjectMapper json,NotificationSettings bot,@Value("${custom-strategies.notifications-enabled:false}")boolean notifications){return new CustomStrategyService(mapper,factors,stocks,dates,json,bot,notifications);}
    @Bean CustomDelivery customDelivery(CustomStrategyMapper mapper,NotificationSettings bot,ObjectProvider<NotificationClient> clients,@Value("${custom-strategies.notifications-enabled:false}")boolean enabled,@Value("${custom-strategies.worker-enabled:true}")boolean worker){return new CustomDelivery(mapper,bot,clients,enabled,worker);}
    public record CustomDelivery(CustomStrategyMapper mapper,NotificationSettings bot,ObjectProvider<NotificationClient> clients,boolean enabled,boolean worker){
        @Scheduled(fixedDelayString="${custom-strategies.delivery-delay-ms:5000}")public void deliver(){if(!enabled||!worker||!bot.enabled)return;var client=clients.getIfAvailable();if(client==null)return;mapper.expireSending();mapper.expirePending();NotificationRow row=null;for(String chat:bot.pollTargets("custom-strategy")){row=mapper.claim(chat,UUID.randomUUID().toString());if(row!=null)break;}if(row==null)return;NotificationClient.Delivery result;try{result=client.send(row.targetChatId,row.payload);}catch(Exception e){result=new NotificationClient.Delivery(NotificationClient.Outcome.UNKNOWN,"CLIENT_FAILED");}String status=switch(result.outcome()){case SUCCESS->"SUCCESS";case UNKNOWN->"UNKNOWN";case REJECTED->"FAILED";case RETRY->row.attempts>=3?"FAILED":"RETRY";};mapper.finish(row.id,row.claimToken,status,status.equals("SUCCESS")?null:"DELIVERY_"+result.outcome());}
    }
}
